import{_ as r,o as t,c as e,a2 as n}from"./chunks/framework.DuPBmefI.js";const d=JSON.parse('{"title":"英华书院 · 年份未注明 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-82f4b96c","school_zh":"英华书院","school_en":"—","grade":"s1","year":"unknown","year_label":"年份未注明","type":"interview","title":"英华书院 · 年份未注明 · 中一 · 面试","anonymous":true,"source_ids":["C1821-YW-U","GUIDE-YWC","HOT22-YWC","YWC-S1-GUIDE-VALUES"],"rounds":["unknown","r1"]},"headers":[],"relativePath":"reports/school-82f4b96c/s1/unknown-interview.md","filePath":"reports/school-82f4b96c/s1/unknown-interview.md"}'),s={name:"reports/school-82f4b96c/s1/unknown-interview.md"};function p(a,o,l,c,g,i){return t(),e("div",null,[...o[0]||(o[0]=[n('<h1 id="英华书院-·-年份未注明-·-中一-·-面试" tabindex="-1">英华书院 · 年份未注明 · 中一 · 面试 <a class="header-anchor" href="#英华书院-·-年份未注明-·-中一-·-面试" aria-label="Permalink to &quot;英华书院 · 年份未注明 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-82f4b96c">← 返回英华书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-yw-u" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-yw-u" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-yw-u}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 中文（口语未注明）</p><p><strong>关爱与学校生活</strong></p><p>谈对关爱座的看法、什么是关爱；小组讨论小学生应否拥有手机、哪种类型的老师最好。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>数字规律</strong></p><p>找出数列6、12、24、48、64之后的下一项。</p></blockquote><h2 id="record-guide-ywc" tabindex="-1">资料来源：英華面試題.pdf <a class="header-anchor" href="#record-guide-ywc" aria-label="Permalink to &quot;资料来源：英華面試題.pdf {#record-guide-ywc}&quot;">​</a></h2><p><strong>资料类型：</strong> 机构整理：历年面试题型</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>个人面谈与分站流程</strong></p><p>一种历史流程的净考核时间约40分钟，连同准备约60至75分钟。考生按编号进入礼堂，领取文具及草稿纸，约用3分钟阅读，再到不同课室完成各站任务。数学以口头心算为主，并非另设正式笔试。</p></blockquote><blockquote><p><strong>语文：</strong> 中文</p><p><strong>阅读准备与理解</strong></p><p>文章设约3道问题，准备时可记笔记。例如阅读「地球生病」主题内容，填入词语、写答案并读出句子；老师可能再追问1至2题。</p><p><strong>观点表达题</strong></p><ul><li>是否认为女生比男生强？校内男女生如何相处？</li><li>怎样看待背诵或朗读的学习方法？</li><li>是否赞成善意的谎言？</li><li>如果担任班长，怎样推广阅读和学习活动？</li><li>网上学习能否取代学校课堂？</li></ul><p><strong>校园与公共议题</strong></p><p>讨论如何帮助学校环保，以及关爱座能否增强公众让座意识。</p><p><strong>小组讨论形式</strong></p><p>历史整理亦包含以上主题的小组讨论形式。个人分站与小组讨论属于不同形式的片段，不表示每位考生在同一场次均经历两者。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>文章理解与生活追问</strong></p><p>朗读或阅读文章后回答约3道问题，例子包括：</p><ul><li>最喜欢什么早餐，为什么？</li><li>如果兄弟姊妹没有吃早餐就上学，你会怎么做？</li><li>文章介绍的互联网主要用途是什么？</li></ul></blockquote><blockquote><p><strong>数学：</strong> 未注明</p><p><strong>口头心算</strong></p><p>面谈流程中包括口头心算任务；具体题目与固定题量未确定。</p></blockquote><blockquote><p><strong>科学：</strong> 未注明</p><p><strong>实验与图像分析</strong></p><p>部分流程在中英文面谈后进入另一课室，进行科学或生活常识交流。机构列出的准备方向包括水的沸腾、光合作用所需条件、设计实验验证原理、处理实验室突发情况，以及指出图片中不合理之处并提出改进。这些为机构准备例题，不能视为每届必考内容。</p></blockquote><h2 id="record-hot22-ywc" tabindex="-1">资料来源：热门港校面试真题集：中学篇.pdf <a class="header-anchor" href="#record-hot22-ywc" aria-label="Permalink to &quot;资料来源：热门港校面试真题集：中学篇.pdf {#record-hot22-ywc}&quot;">​</a></h2><p><strong>资料类型：</strong> 2022/23机构汇编中的历史面试题</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 中文（口语未注明）</p><p><strong>阅读理解</strong></p><p>准备4分钟，阅读文章后回答问题。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗读理解</strong></p><p>准备4分钟后朗读及回答问题。</p><p><strong>早餐情境</strong></p><p>最喜欢什么早餐及原因；若兄弟姐妹未吃早餐就上学，会怎样处理。</p></blockquote><blockquote><p><strong>小组讨论：</strong> 中文（口语未注明）</p><p><strong>环保校园</strong></p><p>讨论如何营造环保校园。</p></blockquote><h2 id="record-ywc-s1-guide-values" tabindex="-1">资料来源：香港学校面试题【协恩 英皇 真光 皇仁 圣保罗 英华】.docx <a class="header-anchor" href="#record-ywc-s1-guide-values" aria-label="Permalink to &quot;资料来源：香港学校面试题【协恩 英皇 真光 皇仁 圣保罗 英华】.docx {#record-ywc-s1-guide-values}&quot;">​</a></h2><p><strong>资料类型：</strong> 机构整理：历史面试题目</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-2" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-2" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 中文</p><p><strong>语言与观点</strong></p><p>包含中文填充；讨论金钱与权力的局限，以及会用什么颜色形容自己并说明原因。</p></blockquote>',34)])])}const h=r(s,[["render",p]]);export{d as __pageData,h as default};
